        super().__init__(name, modified)
        self.size = size


class Directory(Node):
    def __init__(self, name: str, modified: float = 0.0) -> None:
        super().__init__(name, modified)
        self.children: dict[str, Node] = {}

    @property
    def is_dir(self) -> bool:
        return True

    def add(self, node: Node) -> Node:
        raise NotImplementedError


